// ---------- prontos de 1934: só os 4 arquétipos naturais de cada porta (sem cruzamentos) ----------
(function(){
  const r = window.SV_REGRAS && window.SV_REGRAS['1934']; if (!r || !r.prontos) return;
  const naturais = r.arquetipos.filter(a => !a.vertente).map(a => a.n);
  const vistos = new Set();
  r.prontos = r.prontos.filter(p => { if (!naturais.includes(p.arq) || vistos.has(p.arq)) return false; vistos.add(p.arq); return true; });
})();

